// Oracle-only stand-in for the npm `proper-lockfile` package (not present in
// the offline environment). Grants the lock immediately, in-process. Only
// used to let the real upstream `auth-storage.ts` / `models-store.ts` load
// under node for oracle capture; lock contention behavior is NOT captured.
const held = new Set();

async function lock(path) {
  held.add(path);
  let released = false;
  return async () => {
    if (!released) {
      released = true;
      held.delete(path);
    }
  };
}

function lockSync(path) {
  held.add(path);
  let released = false;
  return () => {
    if (!released) {
      released = true;
      held.delete(path);
    }
  };
}

export default { lock, lockSync };
export { lock, lockSync };
